use super::*;use crate::{json,Value,original_group_game};
fn fixture(name:&str)->Option<String>{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().find_map(|p|std::fs::read_to_string(p.join(name)).ok().or_else(||std::fs::read_to_string(p.join("work/parity-audit").join(name)).ok()))}
fn hex(b:impl IntoIterator<Item=u8>)->String{b.into_iter().map(|n|format!("{n:02x}")).collect()}
fn field(kind:i8,max:i16,hp:i16,position:[i16;2],templates:Value)->Game{let mut g=Game::new(0,1,742);let mut b=g.buildings[0].clone();g.map.original=true;g.map.width=64;g.map.height=64;g.map.tiles=vec![0;4096];g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.map.original_tiles=vec![0;4096];g.map.territory=vec![0;4096];g.map.bridge_base=vec![-1;4096];g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.sectors.clear();g.ai_teams.clear();g.native_world=None;g.native_strategy=None;g.native_group_rosters=original_group_game::State::default();b.id=77;b.kind=match kind{0=>"repair",1=>"vehicle",4=>"robot",8=>"radar",_=>"fort"}.into();b.x=f64::from(position[0])*2.;b.y=f64::from(position[1])*2.;b.hp=f64::from(hp);b.max_hp=f64::from(max);b.team=-1;b.product=None;b.remaining_work=None;g.buildings.push(b);g.native_view=Some(([0,0],[800,600]));g.import_native_world(&json!({"nativeWorldBuildings":[{"nativeSlot":0,"kind":kind,"x":position[0],"y":position[1],"hp":hp,"maxHp":max,"buildingId":77}],"nativeBuildingFragments":[{"nativeSlot":0,"templates":templates}]}));g.initialize_native_building_fragments(0);g}
#[test]fn optional_all112_native_build_caller_pools_and_retained_draw_records_match(){let Some(csv)=fixture("v41-building-callers.jsonl")else{return;};let mut count=0;for line in csv.lines(){let r:Value=serde_json::from_str(line).unwrap();let n=|k:&str|r[k].as_i64().unwrap();let s=n("scenario")as usize;let mode=n("mode");let max=[0,1,100,32767][s/4];let hp=if mode==0{100}else{[0,1,80,32767][s/4]};let mut g=field(n("kind")as i8,max,hp,if mode==0{[400,500]}else{[3000,3000]},if mode==0{r["templates"].clone()}else{json!([[0,0,120,0,4,2]])});g.multiplayer=s&1!=0;let w=g.native_world.as_mut().unwrap();for(i,rec)in w.fragments.pools[0].records.iter_mut().enumerate(){rec.bytes=std::array::from_fn(|j|(s*19+i*13+j*7)as u8);rec.set(0,if i<[0,25,49,50][s%4]{100+i as i16}else{-1});}if mode==0{let before=g.original_rng.words;g.initialize_native_building_fragments(0);assert_eq!(g.original_rng.words,before,"41f8f0 itself has no RNG");}else{let w=g.native_world.as_mut().unwrap();for rec in &mut w.fragments.pools[0].records{rec.set(0,-1);}let rec=&mut w.fragments.pools[0].records[0];rec.set(0,100);rec.set(2,200);rec.set(8,1782);rec.set(10,[0,10,-2,-10][s%4]);rec.bytes[12]=0;rec.bytes[13]=4;rec.bytes[14]=(s/4%4)as u8;rec.bytes[15]=1;rec.bytes[16]=2;g.native_building_fragment_tail(77);assert_eq!(hex(g.native_building_fragment_draws().iter().flat_map(|(r,_,_)|r.bytes())),r["queue"]);}
 assert_eq!(hex(g.native_world.as_ref().unwrap().fragments.pools[0].records.iter().flat_map(|r|r.bytes)),r["bytes"],"mode{mode}/kind{}/s{s}",n("kind"));count+=1;}assert_eq!(count,112);}
#[test]fn actual48_removal_pointer_fixtures_keep_the_first_threshold_before_the_inactive_terminator(){let Some(csv)=fixture("v41-building-removal.jsonl")else{return;};let mut count=0;for line in csv.lines(){let r:Value=serde_json::from_str(line).unwrap();let s=r["scenario"].as_u64().unwrap()as usize;let mut g=field(1,1,1,[400,500],json!([[0,0,120,0,4,2]]));let w=g.native_world.as_mut().unwrap();for(i,rec)in w.fragments.pools[0].records.iter_mut().enumerate(){rec.bytes=std::array::from_fn(|j|(s*19+i*7+j*13)as u8);rec.set(0,if i==[50,49,3,50][s%4]{-1}else{100+i as i16});rec.set(10,if i==[0,5,49,49][s%4]{-2}else{123});}let before=w.fragments.pools[0].records;if r["kind"]!=2{Game::retire_native_building_fragment_prefix(w,0);}let expected=(r["fragmentPointer"].as_u64().unwrap()-0x1801000)/18;assert_eq!(w.fragments.starts[0],expected as usize);assert_eq!(w.fragments.pools[0].records,before);count+=1;}assert_eq!(count,48);}
#[test]fn actual_damage_transition_selects_the_subrecord_before_collapse_and_does_not_repeat_on_zero_hp(){let mut g=field(1,1,1,[400,500],json!([[0,0,120,0,4,2]]));let w=g.native_world.as_mut().unwrap();for(i,r)in w.fragments.pools[0].records.iter_mut().enumerate(){r.set(0,if i<8{410+i as i16}else{-1});r.set(10,if i==5{-2}else{99});}let bytes=w.fragments.pools[0].records;g.native_blast_environment(400,484,255,255,false);assert_eq!(g.buildings[0].hp,0.);assert_eq!(g.native_world.as_ref().unwrap().fragments.starts[0],5);assert_eq!(g.native_world.as_ref().unwrap().fragments.pools[0].records,bytes);g.native_world.as_mut().unwrap().fragments.pools[0].records[6].set(10,-2);g.native_blast_environment(400,484,255,255,false);assert_eq!(g.native_world.as_ref().unwrap().fragments.starts[0],5);}
#[test]fn actual_main_advances_every_missing_kind_once_and_dead_tail_uses_minus_two(){for kind in[1,4,8]{let mut g=field(kind,100,80,[400,500],json!([[0,0,120,10,4,2]]));let w=g.native_world.as_mut().unwrap();w.fragments.pools[0].records[0].set(10,10);g.spawn("grunt",0,1800.,1800.,1,None);g.spawn("grunt",1,1900.,1800.,2,None);g.maintain_native_group_rosters();g.step(0.059);assert!(g.native_building_fragment_draws().is_empty());g.step(0.059);assert_eq!(g.native_building_fragment_draws().len(),1,"kind{kind}");assert_eq!(g.native_world.as_ref().unwrap().fragments.pools[0].records[0].bytes[15],1);let before=g.native_building_fragment_draws();g.buildings[0].hp=0.;g.sync_native_world();assert_eq!(g.native_building_fragment_draws(),before);g.native_world.as_mut().unwrap().fragments.pools[0].records[0].bytes[14]=0;g.native_world.as_mut().unwrap().fragments.pools[0].records[0].set(10,2);g.native_building_fragment_tail(77);assert_eq!(g.native_world.as_ref().unwrap().fragments.pools[0].records[0].bytes[14]&2,0,"dead source argument is-2, not100");}}
